{"command":"cat << 'EOF' > task.go
package main

import (
	"crypto/rand"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

type Task struct {
	UUID         string    `json:"uuid"`
	Status       string    `json:"status"`
	ID           int       `json:"id"`
	Summary      string    `json:"summary"`
	Notes        string    `json:"notes"`
	Tags         []string  `json:"tags"`
	Project      string    `json:"project"`
	Priority     string    `json:"priority"`
	DelegatedTo  string    `json:"delegatedto"`
	Subtasks     []string  `json:"subtasks"`
	Dependencies []string  `json:"dependencies"`
	Created      time.Time `json:"created"`
	Resolved     time.Time `json:"resolved"`
	Due          time.Time `json:"due"`
}

func NewUUID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

func (t *Task) Normalise() {
	if t.Tags == nil {
		t.Tags = []string{}
	}
	if t.Subtasks == nil {
		t.Subtasks = []string{}
	}
	if t.Dependencies == nil {
		t.Dependencies = []string{}
	}
	if t.Priority == "" {
		t.Priority = PRIORITY_P2
	}
	t.Project = strings.ToLower(t.Project)
	for i, tag := range t.Tags {
		t.Tags[i] = strings.ToLower(tag)
	}
}

func (t *Task) YAML(includeStatus bool) string {
	t.Normalise()
	var sb strings.Builder

	if includeStatus {
		sb.WriteString(fmt.Sprintf("status: %s\n", t.Status))
	}
	sb.WriteString(fmt.Sprintf("summary: %s\n", t.Summary))

	if t.Notes == "" {
		sb.WriteString("notes: \"\"\n")
	} else {
		sb.WriteString("notes: |-\n")
		lines := strings.Split(t.Notes, "\n")
		for _, line := range lines {
			sb.WriteString(fmt.Sprintf("  %s\n", line))
		}
	}

	if len(t.Tags) == 0 {
		sb.WriteString("tags: []\n")
	} else {
		sb.WriteString("tags:\n")
		for _, tag := range t.Tags {
			sb.WriteString(fmt.Sprintf("- %s\n", tag))
		}
	}

	sb.WriteString(fmt.Sprintf("project: %s\n", t.Project))
	sb.WriteString(fmt.Sprintf("priority: %s\n", t.Priority))
	sb.WriteString(fmt.Sprintf("delegatedto: %q\n", t.DelegatedTo))

	if len(t.Subtasks) == 0 {
		sb.WriteString("subtasks: []\n")
	} else {
		sb.WriteString("subtasks:\n")
		for _, st := range t.Subtasks {
			sb.WriteString(fmt.Sprintf("- %s\n", st))
		}
	}

	if len(t.Dependencies) == 0 {
		sb.WriteString("dependencies: []\n")
	} else {
		sb.WriteString("dependencies:\n")
		for _, dep := range t.Dependencies {
			sb.WriteString(fmt.Sprintf("- %s\n", dep))
		}
	}

	createdStr := "0001-01-01T00:00:00Z"
	if !t.Created.IsZero() {
		createdStr = t.Created.UTC().Format("2006-01-02T15:04:05.999999999Z07:00")
	}
	sb.WriteString(fmt.Sprintf("created: %s\n", createdStr))

	resolvedStr := "0001-01-01T00:00:00Z"
	if !t.Resolved.IsZero() {
		resolvedStr = t.Resolved.UTC().Format("2006-01-02T15:04:05.999999999Z07:00")
	}
	sb.WriteString(fmt.Sprintf("resolved: %s\n", resolvedStr))

	dueStr := "0001-01-01T00:00:00Z"
	if !t.Due.IsZero() {
		dueStr = t.Due.UTC().Format("2006-01-02T15:04:05.999999999Z07:00")
	}
	sb.WriteString(fmt.Sprintf("due: %s\n", dueStr))

	return sb.String()
}

func ParseTaskYAML(data string) (Task, error) {
	t := Task{
		Tags:         []string{},
		Subtasks:     []string{},
		Dependencies: []string{},
		Priority:     PRIORITY_P2,
	}

	lines := strings.Split(data, "\n")
	var currentKey string
	var inNotes bool
	var notesLines []string

	for i := 0; i < len(lines); i++ {
		line := lines[i]

		if inNotes {
			if strings.HasPrefix(line, "  ") {
				notesLines = append(notesLines, strings.TrimPrefix(line, "  "))
				continue
			} else if line == "" && i+1 < len(lines) && strings.HasPrefix(lines[i+1], "  ") {
				notesLines = append(notesLines, "")
				continue
			} else {
				inNotes = false
				t.Notes = strings.Join(notesLines, "\n")
			}
		}

		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		if strings.HasPrefix(trimmed, "- ") {
			val := strings.TrimSpace(strings.TrimPrefix(trimmed, "- "))
			val = strings.Trim(val, "\"'")
			switch currentKey {
			case "tags":
				t.Tags = append(t.Tags, val)
			case "subtasks":
				t.Subtasks = append(t.Subtasks, val)
			case "dependencies":
				t.Dependencies = append(t.Dependencies, val)
			}
			continue
		}

		parts := strings.SplitN(trimmed, ":", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(parts[0]))
		val := strings.TrimSpace(parts[1])

		currentKey = key

		if key == "notes" {
			if strings.HasPrefix(val, "|") {
				inNotes = true
				notesLines = nil
			} else {
				t.Notes = strings.Trim(val, "\"'")
			}
			continue
		}

		val = strings.Trim(val, "\"'")

		switch key {
		case "status":
			t.Status = val
		case "summary":
			t.Summary = val
		case "project":
			t.Project = val
		case "priority":
			t.Priority = val
		case "delegatedto":
			t.DelegatedTo = val
		case "created":
			if tm, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Created = tm.UTC()
			} else if tm, err := time.Parse(time.RFC3339, val); err == nil {
				t.Created = tm.UTC()
			}
		case "resolved":
			if tm, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Resolved = tm.UTC()
			} else if tm, err := time.Parse(time.RFC3339, val); err == nil {
				t.Resolved = tm.UTC()
			}
		case "due":
			if tm, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Due = tm.UTC()
			} else if tm, err := time.Parse(time.RFC3339, val); err == nil {
				t.Due = tm.UTC()
			}
		}
	}

	if inNotes {
		t.Notes = strings.Join(notesLines, "\n")
	}

	t.Normalise()
	return t, nil
}

func (t *Task) Save(repoPath string) error {
	if t.UUID == "" {
