func ParseTaskYAML(data string) (Task, error) {
	t := Task{
		Tags:         []string{},
		Subtasks:     []string{},
		Dependencies: []string{},
		Priority:     PRIORITY_P2,
	}

	lines := strings.Split(data, "\n")
	var currentKey string
	var inNotes bool
	var notesLines []string

	for i := 0; i < len(lines); i++ {
		line := lines[i]

		if inNotes {
			if strings.HasPrefix(line, "  ") {
				notesLines = append(notesLines, strings.TrimPrefix(line, "  "))
				continue
			} else if line == "" && i+1 < len(lines) && strings.HasPrefix(lines[i+1], "  ") {
				notesLines = append(notesLines, "")
				continue
			} else {
				inNotes = false
				t.Notes = strings.Join(notesLines, "\n")
			}
		}

		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		if strings.HasPrefix(trimmed, "- ") {
			val := strings.TrimSpace(strings.TrimPrefix(trimmed, "- "))
			val = strings.Trim(val, "\"'")
