				t.Subtasks = append(t.Subtasks, val)
			case "dependencies":
				t.Dependencies = append(t.Dependencies, val)
			}
			continue
		}

		parts := strings.SplitN(trimmed, ":", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(parts[0]))
		val := strings.TrimSpace(parts[1])

		currentKey = key

		if key == "notes" {
			if strings.HasPrefix(val, "|") {
				inNotes = true
				notesLines = nil
			} else {
				t.Notes = strings.Trim(val, "\"'")
			}
			continue
		}

		val = strings.Trim(val, "\"'")

		switch key {
		case "status":
			t.Status = val
		case "summary":
			t.Summary = val
		case "project":
			t.Project = val
		case "priority":
			t.Priority = val
		case "delegatedto":
			t.DelegatedTo = val
		case "created":
			if tm, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Created = tm.UTC()
			} else if tm, err := time.Parse(time.RFC3339, val); err == nil {
				t.Created = tm.UTC()
			}
		case "resolved":
			if tm, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Resolved = tm.UTC()
			} else if tm, err := time.Parse(time.RFC3339, val); err == nil {
				t.Resolved = tm.UTC()
			}
		case "due":
			if tm, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Due = tm.UTC()
			} else if tm, err := time.Parse(time.RFC3339, val); err == nil {
				t.Due = tm.UTC()
			}
		}
	}

	if inNotes {
		t.Notes = strings.Join(notesLines, "\n")
	}

	t.Normalise()
	return t, nil
}

func (t *Task) Save(repoPath string) error {
	if t.UUID == "" {
		t.UUID = NewUUID()
	}
	if t.Status == "" {
		t.Status = STATUS_PENDING
	}
	t.Normalise()

	dir := filepath.Join(repoPath, t.Status)
	if err := os.MkdirAll(dir, 0755); err != nil {
