{"command":"cat << 'EOF' > query.go
package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

type Query struct {
	Cmd           string    `json:"cmd"`
	IDs           []int     `json:"ids"`
	Tags          []string  `json:"tags"`
	AntiTags      []string  `json:"antitags"`
	Project       string    `json:"project"`
	AntiProjects  []string  `json:"antiprojects"`
	Due           time.Time `json:"due"`
	DateFilter    string    `json:"datefilter"`
	Priority      string    `json:"priority"`
	Template      int       `json:"template"`
	Text          string    `json:"text"`
	IgnoreContext bool      `json:"ignorecontext"`
	Note          string    `json:"note"`
}

func ParseDueDate(s string) (time.Time, error) {
	s = strings.ToLower(strings.TrimSpace(s))
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)

	switch s {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	}

	days := map[string]time.Weekday{
		"sunday":    time.Sunday,
		"sun":       time.Sunday,
		"monday":    time.Monday,
		"mon":       time.Monday,
		"tuesday":   time.Tuesday,
		"tue":       time.Tuesday,
		"wednesday": time.Wednesday,
		"wed":       time.Wednesday,
		"thursday":  time.Thursday,
		"thu":       time.Thursday,
		"friday":    time.Friday,
		"fri":       time.Friday,
		"saturday":  time.Saturday,
		"sat":       time.Saturday,
	}

	if targetDay, ok := days[s]; ok {
		currentDay := today.Weekday()
		daysAhead := int(targetDay) - int(currentDay)
		if daysAhead < 0 {
			daysAhead += 7
		}
		return today.AddDate(0, 0, daysAhead), nil
	}

	if tm, err := time.Parse("2006-01-02", s); err == nil {
		return tm, nil
	}
	if tm, err := time.Parse(time.RFC3339, s); err == nil {
		return tm, nil
	}

	return time.Time{}, fmt.Errorf("invalid date format: %s", s)
}

func IsSubcommand(s string) bool {
	switch strings.ToLower(s) {
	case CMD_NEXT, CMD_ADD, CMD_TEMPLATE, CMD_LOG, CMD_START, CMD_NOTE, CMD_NOTES, CMD_STOP, CMD_DONE, CMD_RESOLVE, CMD_CONTEXT, CMD_MODIFY, CMD_EDIT, CMD_UNDO, CMD_SYNC, CMD_OPEN, CMD_GIT, CMD_REMOVE, CMD_RM, CMD_SHOW_PROJECTS, CMD_SHOW_TAGS, CMD_SHOW_ACTIVE, CMD_SHOW_PAUSED, CMD_SHOW_OPEN, CMD_SHOW_RESOLVED, CMD_SHOW_TEMPLATES, CMD_SHOW_UNORGANISED, CMD_BASH_COMPLETION, CMD_FISH_COMPLETION, CMD_ZSH_COMPLETION, CMD_COMPLETIONS, CMD_HELP, CMD_VERSION:
		return true
	default:
		return false
	}
}

func ParseCmdLine(args []string) Query {
	q := Query{
		Tags:         []string{},
		AntiTags:     []string{},
		AntiProjects: []string{},
		IDs:          []int{},
	}

	var textWords []string
	inNote := false
	var noteWords []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if inNote {
			noteWords = append(noteWords, arg)
			continue
		}

		if arg == "/" {
			inNote = true
			continue
		}

		if arg == "--" {
			q.IgnoreContext = true
			continue
		}

		if IsSubcommand(arg) && q.Cmd == "" {
			q.Cmd = strings.ToLower(arg)
			continue
		}

		// Check comma-separated or single integers as IDs
		if isIDList(arg) {
			for _, idStr := range strings.Split(arg, ",") {
				if id, err := strconv.Atoi(idStr); err == nil && id > 0 {
					q.IDs = append(q.IDs, id)
				}
			}
			continue
		}

		// Priority
		upper := strings.ToUpper(arg)
		if upper == PRIORITY_P0 || upper == PRIORITY_P1 || upper == PRIORITY_P2 || upper == PRIORITY_P3 {
			q.Priority = upper
			continue
		}

		// Project
		lower := strings.ToLower(arg)
		if strings.HasPrefix(lower, "project:") {
			q.Project = strings.TrimPrefix(lower, "project:")
			continue
		}
		if strings.HasPrefix(lower, "-project:") {
			q.AntiProjects = append(q.AntiProjects, strings.TrimPrefix(lower, "-project:"))
			continue
		}

		// Tags
		if strings.HasPrefix(lower, "+") {
			tag := strings.TrimPrefix(lower, "+")
			if tag != "" {
				q.Tags = append(q.Tags, tag)
			}
			continue
		}
		if strings.HasPrefix(lower, "-") {
			tag := strings.TrimPrefix(lower, "-")
			if tag != "" {
				q.AntiTags = append(q.AntiTags, tag)
			}
			continue
		}

		// Due
		if strings.HasPrefix(lower, "due:") {
			dueStr := strings.TrimPrefix(lower, "due:")
			if tm, err := ParseDueDate(dueStr); err == nil {
				q.Due = tm
			}
			continue
		}

		// Template
		if strings.HasPrefix(lower, "template:") {
			tmplStr := strings.TrimPrefix(lower, "template:")
			if id, err := strconv.Atoi(tmplStr); err == nil {
				q.Template = id
			}
			continue
		}

		textWords = append(textWords, arg)
	}

	q.Text = strings.Join(textWords, " ")
	q.Note = strings.Join(noteWords, " ")

	return q
}

func isIDList(s string) bool {
	parts := strings.Split(s, ",")
	for _, p := range parts {
		if p == "" {
			return false
		}
		if _, err := strconv.Atoi(p); err != nil {
			return false
		}
	}
	return true
}

func (q *Query) String() string {
	var parts []string
	for _, tag := range q.Tags {
		parts = append(parts, "+"+tag)
	}
	for _, tag := range q.AntiTags {
		parts = append(parts, "-"+tag)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, proj := range q.AntiProjects {
		parts = append(parts, "-project:"+proj)
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Text != "" {
		parts = append(parts, q.Text)
	}
	return strings.Join(parts, " ")
}
EOF"}

