func IsSubcommand(s string) bool {
	switch strings.ToLower(s) {
	case CMD_NEXT, CMD_ADD, CMD_TEMPLATE, CMD_LOG, CMD_START, CMD_NOTE, CMD_NOTES, CMD_STOP, CMD_DONE, CMD_RESOLVE, CMD_CONTEXT, CMD_MODIFY, CMD_EDIT, CMD_UNDO, CMD_SYNC, CMD_OPEN, CMD_GIT, CMD_REMOVE, CMD_RM, CMD_SHOW_PROJECTS, CMD_SHOW_TAGS, CMD_SHOW_ACTIVE, CMD_SHOW_PAUSED, CMD_SHOW_OPEN, CMD_SHOW_RESOLVED, CMD_SHOW_TEMPLATES, CMD_SHOW_UNORGANISED, CMD_BASH_COMPLETION, CMD_FISH_COMPLETION, CMD_ZSH_COMPLETION, CMD_COMPLETIONS, CMD_HELP, CMD_VERSION:
