func ParseCmdLine(args []string) Query {
	q := Query{
		Tags:         []string{},
		AntiTags:     []string{},
		AntiProjects: []string{},
		IDs:          []int{},
	}

	var textWords []string
	inNote := false
	var noteWords []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if inNote {
			noteWords = append(noteWords, arg)
			continue
		}

		if arg == "/" {
