package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type TaskSet struct {
	Tasks []Task
}

func LoadTaskSet(repoPath string) (*TaskSet, error) {
	ts := &TaskSet{}

	var openTasks []Task
	var otherTasks []Task

	for _, status := range ALL_STATUSES {
		dir := filepath.Join(repoPath, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}

		for _, entry := range entries {
			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".yml") {
				continue
			}

			uuid := strings.TrimSuffix(entry.Name(), ".yml")
			filePath := filepath.Join(dir, entry.Name())
			data, err := os.ReadFile(filePath)
			if err != nil {
				continue
			}

			task, err := ParseTaskYAML(string(data))
			if err != nil {
				continue
			}

			task.UUID = uuid
			task.Status = status

			if status == STATUS_RESOLVED || status == STATUS_TEMPLATE {
				otherTasks = append(otherTasks, task)
			} else {
				openTasks = append(openTasks, task)
			}
		}
	}

	// Sort open tasks by Created time ascending to assign IDs
	sort.Slice(openTasks, func(i, j int) bool {
		return openTasks[i].Created.Before(openTasks[j].Created)
	})

	for i := range openTasks {
		openTasks[i].ID = i + 1
	}

	ts.Tasks = append(openTasks, otherTasks...)
	return ts, nil
}

func (ts *TaskSet) Filter(q Query) []Task {
	var result []Task

	for _, t := range ts.Tasks {
		if !MatchFilter(t, q) {
			continue
		}
		result = append(result, t)
	}

	SortTasksForDisplay(result)
	return result
}

func MatchFilter(t Task, q Query) bool {
	// Tags match
	for _, tag := range q.Tags {
		if !contains(t.Tags, tag) {
			return false
		}
	}

	// AntiTags match
	for _, antiTag := range q.AntiTags {
		if contains(t.Tags, antiTag) {
			return false
		}
	}

	// Project match
	if q.Project != "" && strings.ToLower(t.Project) != strings.ToLower(q.Project) {
		return false
	}

	// AntiProjects match
	for _, antiProj := range q.AntiProjects {
		if strings.ToLower(t.Project) == strings.ToLower(antiProj) {
			return false
		}
	}

	// Priority match
	if q.Priority != "" && t.Priority != q.Priority {
		return false
	}

	// Text search
	if q.Text != "" {
		lowerText := strings.ToLower(q.Text)
		summaryMatch := strings.Contains(strings.ToLower(t.Summary), lowerText)
		notesMatch := strings.Contains(strings.ToLower(t.Notes), lowerText)
		if !summaryMatch && !notesMatch {
			return false
		}
	}

	return true
}

func PriorityRank(p string) int {
	switch p {
	case PRIORITY_P0:
		return 0
	case PRIORITY_P1:
		return 1
	case PRIORITY_P2:
		return 2
	case PRIORITY_P3:
		return 3
	default:
		return 2
	}
}

func SortTasksForDisplay(tasks []Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi, pj := PriorityRank(tasks[i].Priority), PriorityRank(tasks[j].Priority)
		if pi != pj {
			return pi < pj
		}
		return tasks[i].Created.Before(tasks[j].Created)
	})
}

func (ts *TaskSet) GetByID(id int) *Task {
	for i := range ts.Tasks {
		if ts.Tasks[i].ID == id {
			return &ts.Tasks[i]
		}
	}
	return nil
}

func (ts *TaskSet) FilterByIDs(ids []int) []Task {
	var result []Task
	for _, id := range ids {
		if t := ts.GetByID(id); t != nil {
			result = append(result, *t)
		}
	}
	return result
}

func contains(slice []string, val string) bool {
	lowerVal := strings.ToLower(val)
	for _, item := range slice {
		if strings.ToLower(item) == lowerVal {
			return true
		}
	}
	return false
}
