	Ypixel uint16
}

func IsTTY() bool {
	var termios [4]uint64
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func GetTerminalSize() (int, int) {
	ws := winsize{}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if err != 0 || ws.Col == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func FormatDueShort(d time.Time) string {
	if d.IsZero() || d.Year() == 1 {
		return ""
	}
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	dueDay := time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, time.UTC)

	diff := dueDay.Sub(today)
	if diff == 0 {
		return "today"
	}
	if diff == 24*time.Hour {
		return "tomorrow"
	}

	if d.Year() == now.Year() {
		return d.Format("2 Jan")
	}
	return d.Format("2 Jan 2006")
}

func RenderTasksJSON(tasks []Task) {
	if tasks == nil {
		tasks = []Task{}
	}
	data, _ := json.MarshalIndent(tasks, "", "  ")
	fmt.Println(string(data))
}

func RenderTasks(tasks []Task, totalTasks int, truncate bool) {
	if !IsTTY() {
		RenderTasksJSON(tasks)
		return
	}

	if len(tasks) == 0 {
		fmt.Println("0 tasks.")
		return
	}

	if len(tasks) == 1 {
		RenderTaskDetail(tasks[0])
		return
	}

	cols, rows := GetTerminalSize()

	displayTasks := tasks
	maxRows := rows - 4 // Leave room for header, blank lines, summary
	if truncate && maxRows > 0 && len(displayTasks) > maxRows {
		displayTasks = displayTasks[:maxRows]
	}

	// Calculate column widths
	wID := 2
	wPrio := 8
	wTags := 4
	wDue := 3
	wProject := 7

	for _, t := range displayTasks {
		idStr := fmt.Sprintf("%d", t.ID)
		if len(idStr) > wID {
			wID = len(idStr)
		}
		tagsStr := strings.Join(t.Tags, " ")
		if len(tagsStr) > wTags {
			wTags = len(tagsStr)
		}
		dueStr := FormatDueShort(t.Due)
		if len(dueStr) > wDue {
			wDue = len(dueStr)
		}
		if len(t.Project) > wProject {
			wProject = len(t.Project)
		}
	}

	// Calculate summary column width
	wSummary := cols - (wID + wPrio + wTags + wDue + wProject + 10)
	if wSummary < 10 {
		wSummary = 10
	}

	// Header line
	hdr := fmt.Sprintf("%-*s  %-*s  %-*s  %-*s  %-*s  %-*s",
		wID, "ID",
		wPrio, "Priority",
		wTags, "Tags",
		wDue, "Due",
		wProject, "Project",
		wSummary, "Summary",
	)
	if len(hdr) > cols {
		hdr = hdr[:cols]
	} else {
		hdr = hdr + strings.Repeat(" ", cols-len(hdr))
	}

	fmt.Printf("\x1b[4;38;5;250;48;5;232m%s\x1b[0m\r\n", hdr)

	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)

	for i, t := range displayTasks {
		bg := "233"
		if i%2 == 1 {
			bg = "232"
		}

		fg := "250"
		switch t.Priority {
		case PRIORITY_P0:
			fg = "160"
		case PRIORITY_P1:
			fg = "166"
		case PRIORITY_P2:
			fg = "250"
		case PRIORITY_P3:
			fg = "245"
		}

		if t.Status == STATUS_ACTIVE {
			fg = "233"
			bg = "250"
		} else if t.Status == STATUS_PAUSED {
			fg = "250"
			bg = "236"
		}

		dueDay := time.Date(t.Due.Year(), t.Due.Month(), t.Due.Day(), 0, 0, 0, 0, time.UTC)
