{"command":"cat << 'EOF' > git.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func InitRepo(repoPath string) {
	gitDir := filepath.Join(repoPath, ".git")
	if _, err := os.Stat(gitDir); os.IsNotExist(err) {
		err := os.MkdirAll(repoPath, 0755)
		if err != nil {
			ExitError("Failed to create repo directory")
		}
		cmd := exec.Command("git", "-C", repoPath, "init")
		out, err := cmd.CombinedOutput()
		if err != nil {
			ExitError("Failed to initialize git repository: %s", string(out))
		}
		fmt.Printf("Initialized empty Git repository in %s/\n\n", filepath.Join(repoPath, ".git"))
		fmt.Println("Add a remote repository with:\n\n\tdstask git remote add origin <repo>\n")
	}

	for _, status := range ALL_STATUSES {
		dir := filepath.Join(repoPath, status)
		if err := os.MkdirAll(dir, 0755); err != nil {
			ExitError("Failed to create directory in git repository")
		}
	}
}

func RunGitCommand(repoPath string, args ...string) error {
	cmdArgs := append([]string{"-C", repoPath}, args...)
	cmd := exec.Command("git", cmdArgs...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	return cmd.Run()
}

func GitCommit(repoPath string, msg string) error {
	cmdAdd := exec.Command("git", "-C", repoPath, "add", "-A")
	if out, err := cmdAdd.CombinedOutput(); err != nil {
		fmt.Print(string(out))
		return fmt.Errorf("failed to stage changes: %v", err)
	}

	cmdStatus := exec.Command("git", "-C", repoPath, "status", "--porcelain")
	outStatus, _ := cmdStatus.Output()
	if len(strings.TrimSpace(string(outStatus))) == 0 {
		fmt.Printf("\x1b[38;5;245mNo changes detected\n\x1b[0m")
		return nil
	}

	cmdCommit := exec.Command("git", "-C", repoPath, "commit", "-m", msg)
	out, err := cmdCommit.CombinedOutput()
	if err != nil {
		fmt.Print(string(out))
		ExitError("error: failed to commit changes: %v", err)
		return err
	}
	fmt.Printf("\x1b[38;5;245m%s\x1b[0m", string(out))
	return nil
}
EOF"}

