actions.command:
cat << 'EOF' > main.go
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

func main() {
	cfg := GetConfig()
	args := os.Args[1:]

	if len(args) > 0 && args[0] == CMD_COMPLETIONS {
		InitRepo(cfg.Repo)
		ts, _ := LoadTaskSet(cfg.Repo)
		Completions(ts, args[1:])
		return
	}

	if len(args) > 0 && args[0] == CMD_BASH_COMPLETION {
		fmt.Print(BASH_COMPLETION)
		return
	}
	if len(args) > 0 && args[0] == CMD_ZSH_COMPLETION {
		fmt.Print(ZSH_COMPLETION)
		return
	}
	if len(args) > 0 && args[0] == CMD_FISH_COMPLETION {
		fmt.Print(FISH_COMPLETION)
		return
	}

	cmdQuery := ParseCmdLine(args)

	if cmdQuery.Cmd == CMD_HELP {
		if len(args) > 1 {
			ShowHelp(args[1])
		} else {
			ShowHelp("help")
		}
		return
	}

	if cmdQuery.Cmd == CMD_VERSION {
		fmt.Printf("Version: %s\nGit commit: %s\nBuild date: %s\n", VERSION, GIT_COMMIT, BUILD_DATE)
		return
	}

	InitRepo(cfg.Repo)
	state := LoadState(cfg.Repo)

	// Context handling
	var contextQuery Query
	if cfg.Context != "" {
		contextQuery = ParseCmdLine(strings.Fields(cfg.Context))
	} else {
		contextQuery = state.Context
	}

	if cmdQuery.Cmd == CMD_CONTEXT {
		if len(args) > 1 && args[1] == "none" {
			state.Context = Query{}
			SaveState(cfg.Repo, state)
		} else if len(args) > 1 {
			ctxArgs := args[1:]
			state.Context = ParseCmdLine(ctxArgs)
			SaveState(cfg.Repo, state)
		} else {
			if state.Context.String() != "" {
				fmt.Println(state.Context.String())
			} else {
				fmt.Println()
			}
		}
		return
	}

	ts, err := LoadTaskSet(cfg.Repo)
	if err != nil {
		ExitError("Failed to load tasks: %v", err)
	}

	// Determine active command
	cmd := cmdQuery.Cmd
	if cmd == "" {
		cmd = CMD_NEXT
	}

	// Combined query for filtering
	combinedQuery := cmdQuery
	if !cmdQuery.IgnoreContext {
		combinedQuery.Tags = append(combinedQuery.Tags, contextQuery.Tags...)
		combinedQuery.AntiTags = append(combinedQuery.AntiTags, contextQuery.AntiTags...)
		if combinedQuery.Project == "" {
			combinedQuery.Project = contextQuery.Project
		}
		combinedQuery.AntiProjects = append(combinedQuery.AntiProjects, contextQuery.AntiProjects...)
	}

	switch cmd {
	case CMD_NEXT, CMD_SHOW_OPEN:
		tasks := ts.Filter(combinedQuery)
		// Only display open tasks
		var openTasks []Task
		for _, t := range tasks {
			if t.Status != STATUS_RESOLVED && t.Status != STATUS_TEMPLATE {
				openTasks = append(openTasks, t)
			}
		}
		truncate := (cmd == CMD_NEXT)
		RenderTasks(openTasks, len(openTasks), truncate)

	case CMD_SHOW_ACTIVE:
		tasks := ts.Filter(combinedQuery)
		var activeTasks []Task
		for _, t := range tasks {
			if t.Status == STATUS_ACTIVE {
				activeTasks = append(activeTasks, t)
			}
		}
		RenderTasks(activeTasks, len(activeTasks), false)

	case CMD_SHOW_PAUSED:
		tasks := ts.Filter(combinedQuery)
		var pausedTasks []Task
		for _, t := range tasks {
			if t.Status == STATUS_PAUSED {
				pausedTasks = append(pausedTasks, t)
			}
		}
		RenderTasks(pausedTasks, len(pausedTasks), false)

	case CMD_SHOW_RESOLVED:
		tasks := ts.Filter(combinedQuery)
		var resolvedTasks []Task
		for _, t := range tasks {
			if t.Status == STATUS_RESOLVED {
				resolvedTasks = append(resolvedTasks, t)
			}
		}
		if len(resolvedTasks) > 1000 {
			resolvedTasks = resolvedTasks[len(resolvedTasks)-1000:]
		}
		RenderTasks(resolvedTasks, len(resolvedTasks), false)

	case CMD_SHOW_TEMPLATES:
		tasks := ts.Filter(combinedQuery)
		var tmplTasks []Task
		for _, t := range tasks {
			if t.Status == STATUS_TEMPLATE {
				tmplTasks = append(tmplTasks, t)
			}
		}
		RenderTasks(tmplTasks, len(tmplTasks), false)

	case CMD_SHOW_UNORGANISED:
		tasks := ts.Filter(combinedQuery)
		var unorgTasks []Task
		for _, t := range tasks {
			if t.Status != STATUS_RESOLVED && t.Status != STATUS_TEMPLATE && len(t.Tags) == 0 && t.Project == "" {
				unorgTasks = append(unorgTasks, t)
			}
		}
		RenderTasks(unorgTasks, len(unorgTasks), false)

	case CMD_SHOW_PROJECTS:
		projectsMap := make(map[string]*ProjectInfo)
		var projOrder []string

		for _, t := range ts.Tasks {
			if t.Project == "" {
				continue
			}
			pName := strings.ToLower(t.Project)
			info, exists := projectsMap[pName]
			if !exists {
				info = &ProjectInfo{
					Name:     pName,
					Created:  t.Created,
					Priority: PRIORITY_P2,
				}
				projectsMap[pName] = info
				projOrder = append(projOrder, pName)
			}

			info.TaskCount++
			if t.Status == STATUS_RESOLVED {
				info.ResolvedCount++
			}
			if t.Status == STATUS_ACTIVE {
				info.Active = true
			}
			if t.Created.Before(info.Created) {
				info.Created = t.Created
			}
		}

		var projList []ProjectInfo
		for _, name := range projOrder {
			projList = append(projList, *projectsMap[name])
		}
		RenderProjects(projList)

	case CMD_SHOW_TAGS:
		tagMap := make(map[string]bool)
		for _, t := range ts.Tasks {
			if t.Status != STATUS_RESOLVED && t.Status != STATUS_TEMPLATE {
				for _, tag := range t.Tags {
					tagMap[tag] = true
				}
			}
		}
		var tagList []string
		for tag := range tagMap {
			tagList = append(tagList, tag)
		}
		SortTasksForDisplay(nil) // helper
		for _, tag := range tagList {
			fmt.Println(tag)
		}

	case CMD_ADD, CMD_LOG, CMD_TEMPLATE:
		if cmdQuery.Text == "" && cmdQuery.Template == 0 && len(cmdQuery.IDs) == 0 {
			ExitError("task description or template required")
		}

		if cmd == CMD_TEMPLATE && len(cmdQuery.IDs) > 0 {
			// Convert existing task to template
			for _, id := range cmdQuery.IDs {
				task := ts.GetByID(id)
				if task == nil {
					ExitError("no open task with ID %d exists", id)
				}
				oldPath := filepath.Join(cfg.Repo, task.Status, task.UUID+".yml")
				task.Status = STATUS_TEMPLATE
				newPath := filepath.Join(cfg.Repo, STATUS_TEMPLATE, task.UUID+".yml")
				_ = os.Rename(oldPath, newPath)
				_ = task.Save(cfg.Repo)
				GitCommit(cfg.Repo, fmt.Sprintf("Changed %d: %s to Template", task.ID, task.Summary))
			}
			return
		}

		var task Task
		if cmdQuery.Template > 0 {
			tmplTask := ts.GetByID(cmdQuery.Template)
			if tmplTask == nil {
				ExitError("no task template with ID %d exists", cmdQuery.Template)
			}
			task = *tmplTask
			task.UUID = NewUUID()
		}

		if cmdQuery.Text != "" {
			task.Summary = cmdQuery.Text
		}

		if !cmdQuery.IgnoreContext {
			task.Tags = append(task.Tags, contextQuery.Tags...)
			if task.Project == "" {
				task.Project = contextQuery.Project
			}
		}

		task.Tags = append(task.Tags, cmdQuery.Tags...)
		if cmdQuery.Project != "" {
			task.Project = cmdQuery.Project
		}
		if cmdQuery.Priority != "" {
			task.Priority = cmdQuery.Priority
		}
		if !cmdQuery.Due.IsZero() {
			task.Due = cmdQuery.Due
		}
		if cmdQuery.Note != "" {
			if task.Notes != "" {
				task.Notes += "\n" + cmdQuery.Note
			} else {
				task.Notes = cmdQuery.Note
			}
		}

		now := time.Now().UTC()
		task.Created = now

		if cmd == CMD_LOG {
			task.Status = STATUS_RESOLVED
			task.Resolved = now
		} else if cmd == CMD_TEMPLATE {
			task.Status = STATUS_TEMPLATE
		} else {
			task.Status = STATUS_PENDING
		}

		_ = task.Save(cfg.Repo)

		// Get newly assigned ID
		tsNew, _ := LoadTaskSet(cfg.Repo)
		assignedID := 0
		if tNew := tsNew.GetByID(task.ID); tNew != nil {
			assignedID = tNew.ID
		} else {
			for _, t := range tsNew.Tasks {
				if t.UUID == task.UUID {
					assignedID = t.ID
					break
				}
			}
		}

		if contextQuery.String() != "" && !cmdQuery.IgnoreContext {
			fmt.Printf("\x1b[33mActive context: %s\x1b[0m\n\n", contextQuery.String())
		}

		if cmd == CMD_LOG {
			fmt.Printf("Logged %s\n", task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Logged %s", task.Summary))
		} else if cmd == CMD_TEMPLATE {
			fmt.Printf("Created Template %d: %s\n", assignedID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Created Template %d: %s", assignedID, task.Summary))
		} else {
			fmt.Printf("Added %d: %s\n", assignedID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Added %d: %s", assignedID, task.Summary))
		}

	case CMD_START:
		if len(cmdQuery.IDs) == 0 && cmdQuery.Text != "" {
			// Add and start
			task := Task{
				Summary:  cmdQuery.Text,
				Status:   STATUS_ACTIVE,
				Created:  time.Now().UTC(),
				Priority: PRIORITY_P2,
			}
			if !cmdQuery.IgnoreContext {
				task.Tags = append(task.Tags, contextQuery.Tags...)
				if task.Project == "" {
					task.Project = contextQuery.Project
				}
			}
			task.Tags = append(task.Tags, cmdQuery.Tags...)
			if cmdQuery.Project != "" {
				task.Project = cmdQuery.Project
			}
			if cmdQuery.Priority != "" {
				task.Priority = cmdQuery.Priority
			}
			if cmdQuery.Note != "" {
				task.Notes = cmdQuery.Note
			}
			_ = task.Save(cfg.Repo)

			tsNew, _ := LoadTaskSet(cfg.Repo)
			assignedID := 0
			for _, t := range tsNew.Tasks {
				if t.UUID == task.UUID {
					assignedID = t.ID
					break
				}
			}
			fmt.Printf("Started %d: %s\n", assignedID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Started %d: %s", assignedID, task.Summary))
			return
		}

		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		for _, id := range cmdQuery.IDs {
			task := ts.GetByID(id)
			if task == nil {
				ExitError("no open task with ID %d exists", id)
			}

			if task.Notes != "" {
				fmt.Printf("\nNotes on task %d:\n\x1b[38;5;245m%s\x1b[0m\n\n", id, task.Notes)
			}

			oldPath := filepath.Join(cfg.Repo, task.Status, task.UUID+".yml")
			task.Status = STATUS_ACTIVE
			newPath := filepath.Join(cfg.Repo, STATUS_ACTIVE, task.UUID+".yml")
			if oldPath != newPath {
				_ = os.Rename(oldPath, newPath)
			}
			_ = task.Save(cfg.Repo)
			fmt.Printf("\nStarted %d: %s\n", task.ID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Started %d: %s", task.ID, task.Summary))
		}

	case CMD_STOP:
		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		for _, id := range cmdQuery.IDs {
			task := ts.GetByID(id)
			if task == nil {
				ExitError("no open task with ID %d exists", id)
			}

			if err := ValidateTransition(task.Status, STATUS_PAUSED); err != nil {
				ExitError(err.Error())
			}

			if cmdQuery.Note != "" || cmdQuery.Text != "" {
				closingNote := cmdQuery.Note
				if closingNote == "" {
					closingNote = cmdQuery.Text
				}
				if task.Notes != "" {
					task.Notes += "\n" + closingNote
				} else {
					task.Notes = closingNote
				}
			}

			if task.Notes != "" && cmdQuery.Text == "" && cmdQuery.Note == "" {
				fmt.Printf("\nNotes on task %d:\n\x1b[38;5;245m%s\x1b[0m\n\n", id, task.Notes)
			}

			oldPath := filepath.Join(cfg.Repo, task.Status, task.UUID+".yml")
			task.Status = STATUS_PAUSED
			newPath := filepath.Join(cfg.Repo, STATUS_PAUSED, task.UUID+".yml")
			if oldPath != newPath {
				_ = os.Rename(oldPath, newPath)
			}
			_ = task.Save(cfg.Repo)
			fmt.Printf("\nStopped %d: %s\n", task.ID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Stopped %d: %s", task.ID, task.Summary))
		}

	case CMD_DONE, CMD_RESOLVE:
		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		for _, id := range cmdQuery.IDs {
			task := ts.GetByID(id)
			if task == nil {
				ExitError("no open task with ID %d exists", id)
			}

			if cmdQuery.Note != "" || cmdQuery.Text != "" {
				closingNote := cmdQuery.Note
				if closingNote == "" {
					closingNote = cmdQuery.Text
				}
				if task.Notes != "" {
					task.Notes += "\n" + closingNote
				} else {
					task.Notes = closingNote
				}
			}

			oldPath := filepath.Join(cfg.Repo, task.Status, task.UUID+".yml")
			task.Status = STATUS_RESOLVED
			task.Resolved = time.Now().UTC()
			newPath := filepath.Join(cfg.Repo, STATUS_RESOLVED, task.UUID+".yml")
			if oldPath != newPath {
				_ = os.Rename(oldPath, newPath)
			}
			_ = task.Save(cfg.Repo)
			fmt.Printf("\nResolved %d: %s\n", task.ID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Resolved %d: %s", task.ID, task.Summary))
		}

	case CMD_REMOVE, CMD_RM:
		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		for _, id := range cmdQuery.IDs {
			task := ts.GetByID(id)
			if task == nil {
				ExitError("no open task with ID %d exists", id)
			}

			fmt.Printf("%d: %s\n\n", task.ID, task.Summary)
			filePath := filepath.Join(cfg.Repo, task.Status, task.UUID+".yml")
			_ = os.Remove(filePath)
			fmt.Printf("Removed: %d: %s\n", task.ID, task.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Removed: %d: %s", task.ID, task.Summary))
		}

	case CMD_MODIFY:
		targetTasks := ts.FilterByIDs(cmdQuery.IDs)
		if len(cmdQuery.IDs) == 0 {
			// Operate on current context tasks
			targetTasks = ts.Filter(combinedQuery)
			if len(targetTasks) == 0 {
				fmt.Println("No tasks to modify.")
				return
			}
			fmt.Printf("Modify %d tasks in context? (y/n): ", len(targetTasks))
			reader := bufio.NewReader(os.Stdin)
			ans, _ := reader.ReadString('\n')
			if !strings.HasPrefix(strings.ToLower(strings.TrimSpace(ans)), "y") {
				return
			}
		}

		for _, task := range targetTasks {
			tPtr := ts.GetByID(task.ID)
			if tPtr == nil {
				continue
			}

			// Apply modify filters
			for _, tag := range cmdQuery.Tags {
				if !contains(tPtr.Tags, tag) {
					tPtr.Tags = append(tPtr.Tags, tag)
				}
			}
			for _, antiTag := range cmdQuery.AntiTags {
				var newTags []string
				for _, tag := range tPtr.Tags {
					if strings.ToLower(tag) != strings.ToLower(antiTag) {
						newTags = append(newTags, tag)
					}
				}
				tPtr.Tags = newTags
			}

			if cmdQuery.Project != "" {
				tPtr.Project = cmdQuery.Project
			}
			for _, antiProj := range cmdQuery.AntiProjects {
				if strings.ToLower(tPtr.Project) == strings.ToLower(antiProj) {
					tPtr.Project = ""
				}
			}

			if cmdQuery.Priority != "" {
				tPtr.Priority = cmdQuery.Priority
			}

			_ = tPtr.Save(cfg.Repo)
			fmt.Printf("\nModified %d: %s\n", tPtr.ID, tPtr.Summary)
			GitCommit(cfg.Repo, fmt.Sprintf("Modified %d: %s", tPtr.ID, tPtr.Summary))
		}

	case CMD_NOTE, CMD_NOTES:
		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		task := ts.GetByID(cmdQuery.IDs[0])
		if task == nil {
			ExitError("no open task with ID %d exists", cmdQuery.IDs[0])
		}

		if cmdQuery.Text != "" || cmdQuery.Note != "" {
			text := cmdQuery.Text
			if cmdQuery.Note != "" {
				text = cmdQuery.Note
			}
			if task.Notes != "" {
				task.Notes += "\n" + text
			} else {
				task.Notes = text
			}
			_ = task.Save(cfg.Repo)
			GitCommit(cfg.Repo, fmt.Sprintf("Edit note %d: %s", task.ID, task.Summary))
			return
		}

		// Interactive editor for notes
		tmpFile, err := os.CreateTemp("", fmt.Sprintf("dstask.*.%d-%s.md", task.ID, slugify(task.Summary)))
		if err != nil {
			ExitError("failed to create temp file")
		}
		defer os.Remove(tmpFile.Name())

		_, _ = tmpFile.WriteString(task.Notes)
		tmpFile.Close()

		cmdEd := exec.Command("sh", "-c", fmt.Sprintf("%s %s", cfg.Editor, tmpFile.Name()))
		cmdEd.Stdout = os.Stdout
		cmdEd.Stderr = os.Stderr
		cmdEd.Stdin = os.Stdin
		if err := cmdEd.Run(); err != nil {
			ExitError("Failed to run $EDITOR")
		}

		newContent, _ := os.ReadFile(tmpFile.Name())
		fmt.Printf("\nEdit note %d: %s\n", task.ID, task.Summary)
		task.Notes = string(newContent)
		_ = task.Save(cfg.Repo)
		GitCommit(cfg.Repo, fmt.Sprintf("Edit note %d: %s", task.ID, task.Summary))

	case CMD_EDIT:
		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		task := ts.GetByID(cmdQuery.IDs[0])
		if task == nil {
			ExitError("no open task with ID %d exists", cmdQuery.IDs[0])
		}

		tmpFile, err := os.CreateTemp("", fmt.Sprintf("dstask.*.%d-%s.yml", task.ID, slugify(task.Summary)))
		if err != nil {
			ExitError("failed to create temp file")
		}
		defer os.Remove(tmpFile.Name())

		_, _ = tmpFile.WriteString(task.YAML(true))
		tmpFile.Close()

		cmdEd := exec.Command("sh", "-c", fmt.Sprintf("%s %s", cfg.Editor, tmpFile.Name()))
		cmdEd.Stdout = os.Stdout
		cmdEd.Stderr = os.Stderr
		cmdEd.Stdin = os.Stdin
		if err := cmdEd.Run(); err != nil {
			ExitError("Failed to run $EDITOR")
		}

		newContent, _ := os.ReadFile(tmpFile.Name())
		editedTask, err := ParseTaskYAML(string(newContent))
		if err != nil {
			ExitError("Failed to parse edited task: %v", err)
		}

		oldStatus := task.Status
		editedTask.UUID = task.UUID
		editedTask.ID = task.ID

		if editedTask.Status != oldStatus {
			oldPath := filepath.Join(cfg.Repo, oldStatus, task.UUID+".yml")
			_ = os.Remove(oldPath)
		}

		_ = editedTask.Save(cfg.Repo)
		fmt.Printf("\nEdited %d: %s\n", editedTask.ID, editedTask.Summary)
		GitCommit(cfg.Repo, fmt.Sprintf("Edited %d: %s", editedTask.ID, editedTask.Summary))

	case CMD_OPEN:
		if len(cmdQuery.IDs) == 0 {
			ExitError("task ID required")
		}

		urlRegex := regexp.MustCompile(`https?://[^\s)]+`)
		for _, id := range cmdQuery.IDs {
			task := ts.GetByID(id)
			if task == nil {
				continue
			}

			urls := urlRegex.FindAllString(task.Summary+" "+task.Notes, -1)
			if len(urls) == 0 {
				continue
			}

			browser := cfg.Browser
			if browser == "" {
				browser = "xdg-open"
			}

			for _, u := range urls {
				cmdBr := exec.Command(browser, u)
				if err := cmdBr.Run(); err != nil {
					ExitError("Failed to open browser")
				}
			}
		}

	case CMD_UNDO:
		n := 1
		if len(args) > 1 {
			if parsedN, err := strconv.Atoi(args[1]); err == nil && parsedN > 0 {
				n = parsedN
			}
		}

		for i := 0; i < n; i++ {
			if err := RunGitCommand(cfg.Repo, "revert", "--no-edit", "HEAD"); err != nil {
				ExitError("Failed to undo commit")
			}
		}

	case CMD_SYNC:
		if err := RunGitCommand(cfg.Repo, "pull"); err != nil {
			ExitError("Failed to run git cmd.")
		}
		if err := RunGitCommand(cfg.Repo, "push"); err != nil {
			ExitError("Failed to run git cmd.")
		}

	case CMD_GIT:
		if err := RunGitCommand(cfg.Repo, args[1:]...); err != nil {
			os.Exit(1)
		}
	}
}

func slugify(s string) string {
	s = strings.ToLower(s)
	reg := regexp.MustCompile(`[^a-z0-9]+`)
	s = reg.ReplaceAllString(s, "-")
	return strings.Trim(s, "-")
}
