	Dependencies []string  `json:"-"`
	Created      time.Time `json:"created"`
	Resolved     time.Time `json:"resolved"`
	Due          time.Time `json:"due"`
}

func NewUUID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

func (t *Task) Normalise() {
	if t.Tags == nil {
		t.Tags = []string{}
	}
	if t.Subtasks == nil {
		t.Subtasks = []string{}
	}
	if t.Dependencies == nil {
		t.Dependencies = []string{}
	}
	if t.Priority == "" {
		t.Priority = PRIORITY_P2
	}
	t.Project = strings.ToLower(t.Project)
	for i, tag := range t.Tags {
		t.Tags[i] = strings.ToLower(tag)
	}
}

func (t *Task) YAML(includeStatus bool) string {
	t.Normalise()
	var sb strings.Builder

	if includeStatus {
		sb.WriteString(fmt.Sprintf("status: %s\n", t.Status))
	}
	sb.WriteString(fmt.Sprintf("summary: %s\n", t.Summary))

	if t.Notes == "" {
		sb.WriteString("notes: \"\"\n")
	} else {
		sb.WriteString("notes: |-\n")
		lines := strings.Split(t.Notes, "\n")
		for _, line := range lines {
			sb.WriteString(fmt.Sprintf("  %s\n", line))
		}
	}

	if len(t.Tags) == 0 {
		sb.WriteString("tags: []\n")
	} else {
		sb.WriteString("tags:\n")
		for _, tag := range t.Tags {
			sb.WriteString(fmt.Sprintf("- %s\n", tag))
		}
	}

	sb.WriteString(fmt.Sprintf("project: %s\n", t.Project))
	sb.WriteString(fmt.Sprintf("priority: %s\n", t.Priority))
	sb.WriteString(fmt.Sprintf("delegatedto: %q\n", t.DelegatedTo))

	if len(t.Subtasks) == 0 {
		sb.WriteString("subtasks: []\n")
	} else {
		sb.WriteString("subtasks:\n")
		for _, st := range t.Subtasks {
			sb.WriteString(fmt.Sprintf("- %s\n", st))
		}
	}

	if len(t.Dependencies) == 0 {
		sb.WriteString("dependencies: []\n")
	} else {
		sb.WriteString("dependencies:\n")
		for _, dep := range t.Dependencies {
			sb.WriteString(fmt.Sprintf("- %s\n", dep))
		}
	}

	createdStr := "0001-01-01T00:00:00Z"
	if !t.Created.IsZero() {
		createdStr = t.Created.UTC().Format("2006-01-02T15:04:05.999999999Z07:00")
	}
	sb.WriteString(fmt.Sprintf("created: %s\n", createdStr))

	resolvedStr := "0001-01-01T00:00:00Z"
	if !t.Resolved.IsZero() {
		resolvedStr = t.Resolved.UTC().Format("2006-01-02T15:04:05.999999999Z07:00")
	}
