			switch currentKey {
			case "tags":
				t.Tags = append(t.Tags, val)
			case "subtasks":
				t.Subtasks = append(t.Subtasks, val)
			case "dependencies":
				t.Dependencies = append(t.Dependencies, val)
			}
			continue
		}

		parts := strings.SplitN(trimmed, ":", 2)
		if len(parts) != 2 {
