{"command":"cat << 'EOF' > render.go
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"strings"
	"syscall"
	"time"
	"unsafe"
)

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func IsTTY() bool {
	var termios [4]uint64
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func GetTerminalSize() (int, int) {
	ws := winsize{}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if err != 0 || ws.Col == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func FormatDueShort(d time.Time) string {
	if d.IsZero() || d.Year() == 1 {
		return ""
	}
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	dueDay := time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, time.UTC)

	diff := dueDay.Sub(today)
	if diff == 0 {
		return "today"
	}
	if diff == 24*time.Hour {
		return "tomorrow"
	}

	if d.Year() == now.Year() {
		return d.Format("2 Jan")
	}
	return d.Format("2 Jan 2006")
}

func RenderTasksJSON(tasks []Task) {
	if tasks == nil {
		tasks = []Task{}
	}
	data, _ := json.MarshalIndent(tasks, "", "  ")
	fmt.Print(string(data))
	if len(tasks) > 0 {
		fmt.Println()
	}
}

func RenderTasks(tasks []Task, totalTasks int, truncate bool) {
	if !IsTTY() {
		RenderTasksJSON(tasks)
		return
	}

	if len(tasks) == 0 {
		fmt.Println("0 tasks.")
		return
	}

	if len(tasks) == 1 {
		RenderTaskDetail(tasks[0])
		return
	}

	cols, rows := GetTerminalSize()

	displayTasks := tasks
	maxRows := rows - 4
	if truncate && maxRows > 0 && len(displayTasks) > maxRows {
		displayTasks = displayTasks[:maxRows]
	}

	wID := 2
	wPrio := 8
	wTags := 4
	wDue := 3
	wProject := 7

	for _, t := range displayTasks {
		idStr := fmt.Sprintf("%d", t.ID)
		if len(idStr) > wID {
			wID = len(idStr)
		}
		tagsStr := strings.Join(t.Tags, " ")
		if len(tagsStr) > wTags {
			wTags = len(tagsStr)
		}
		dueStr := FormatDueShort(t.Due)
		if len(dueStr) > wDue {
			wDue = len(dueStr)
		}
		if len(t.Project) > wProject {
			wProject = len(t.Project)
		}
	}

	wSummary := cols - (wID + wPrio + wTags + wDue + wProject + 10)
	if wSummary < 10 {
		wSummary = 10
	}

	hdr := fmt.Sprintf("%-*s  %-*s  %-*s  %-*s  %-*s  %-*s",
		wID, "ID",
		wPrio, "Priority",
		wTags, "Tags",
		wDue, "Due",
		wProject, "Project",
		wSummary, "Summary",
	)
	if len(hdr) > cols {
		hdr = hdr[:cols]
	} else {
		hdr = hdr + strings.Repeat(" ", cols-len(hdr))
	}

	fmt.Printf("\x1b[4;38;5;250;48;5;232m%s\x1b[0m\r\n", hdr)

	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)

	for i, t := range displayTasks {
		bg := "233"
		if i%2 == 1 {
			bg = "232"
		}

		fg := "250"
		switch t.Priority {
		case PRIORITY_P0:
			fg = "160"
		case PRIORITY_P1:
			fg = "166"
		case PRIORITY_P2:
			fg = "250"
		case PRIORITY_P3:
			fg = "245"
		}

		if t.Status == STATUS_ACTIVE {
			fg = "233"
			bg = "250"
		} else if t.Status == STATUS_PAUSED {
			fg = "250"
			bg = "236"
		}

		dueDay := time.Date(t.Due.Year(), t.Due.Month(), t.Due.Day(), 0, 0, 0, 0, time.UTC)
		if t.Due.Year() > 1 && dueDay.Equal(today) && t.Status != STATUS_ACTIVE && t.Status != STATUS_PAUSED {
			fg = "166"
		}

		idStr := fmt.Sprintf("%d", t.ID)
		prioStr := t.Priority
		tagsStr := strings.Join(t.Tags, " ")
		dueStr := FormatDueShort(t.Due)
		projStr := t.Project

		summaryText := t.Summary
		hasNote := t.Notes != ""

		cellID := fmt.Sprintf("%-*s", wID, idStr)
		cellPrio := fmt.Sprintf("%-*s", wPrio, prioStr)
		cellTags := fmt.Sprintf("%-*s", wTags, tagsStr)
		cellDue := fmt.Sprintf("%-*s", wDue, dueStr)
		cellProj := fmt.Sprintf("%-*s", wProject, projStr)

		rowText := fmt.Sprintf("%s  %s  %s  %s  %s  ", cellID, cellPrio, cellTags, cellDue, cellProj)

		fmt.Printf("\x1b[0;38;5;%s;48;5;%sm%s", fg, bg, rowText)

		remWidth := cols - len(rowText)
		if remWidth > 0 {
			if hasNote {
				firstLine := strings.Split(t.Notes, "\n")[0]
				notePreview := " " + firstLine
				if len(summaryText)+len(notePreview) <= remWidth {
					fmt.Printf("%s\x1b[38;5;240m%s\x1b[38;5;%sm%s",
						summaryText,
						notePreview,
						fg,
						strings.Repeat(" ", remWidth-len(summaryText)-len(notePreview)),
					)
				} else if len(summaryText) < remWidth {
					availNote := remWidth - len(summaryText)
					if availNote > len(notePreview) {
						availNote = len(notePreview)
					}
					fmt.Printf("%s\x1b[38;5;240m%s\x1b[38;5;%sm%s",
						summaryText,
						notePreview[:availNote],
						fg,
						strings.Repeat(" ", remWidth-len(summaryText)-availNote),
					)
				} else {
					fmt.Printf("%-*s", remWidth, summaryText[:remWidth])
				}
			} else {
				if len(summaryText) > remWidth {
					summaryText = summaryText[:remWidth]
				}
				fmt.Printf("%-*s", remWidth, summaryText)
			}
		}

		fmt.Printf("\x1b[0m\r\n")
	}

	fmt.Printf("\r\n")
	if len(displayTasks) < totalTasks {
		fmt.Printf("%d/%d tasks shown.\r\n", len(displayTasks), totalTasks)
	} else {
		fmt.Printf("%d tasks.\r\n", totalTasks)
	}
}

func RenderTaskDetail(t Task) {
	if !IsTTY() {
		RenderTasksJSON([]Task{t})
		return
	}

	cols, _ := GetTerminalSize()

	hdr := fmt.Sprintf("%-10s%-*s", "Name", cols-10, "Value")
	fmt.Printf("\x1b[4;38;5;250;48;5;232m%s\x1b[0m\r\n", hdr)

	rows := [][2]string{
		{"ID", fmt.Sprintf("%d", t.ID)},
		{"Priority", t.Priority},
		{"Summary", t.Summary},
		{"Status", t.Status},
		{"Project", t.Project},
		{"Tags", strings.Join(t.Tags, ", ")},
		{"UUID", t.UUID},
		{"Created", t.Created.Format("2006-01-02 15:04:05 -0700 MST")},
	}

	if !t.Due.IsZero() && t.Due.Year() > 1 {
		rows = append(rows, [2]string{"Due", t.Due.Format("2006-01-02 15:04:05 -0700 MST")})
	}
	if !t.Resolved.IsZero() && t.Resolved.Year() > 1 {
		rows = append(rows, [2]string{"Resolved", t.Resolved.Format("2006-01-02 15:04:05 -0700 MST")})
	}
	if t.Notes != "" {
		rows = append(rows, [2]string{"Notes", t.Notes})
	}

	for i, r := range rows {
		bg := "233"
		if i%2 == 1 {
			bg = "232"
		}
		valStr := r[1]
		valWidth := cols - 10
		if len(valStr) > valWidth {
			valStr = valStr[:valWidth]
		}
		line := fmt.Sprintf("%-10s%-*s", r[0], valWidth, valStr)
		fmt.Printf("\x1b[0;38;5;250;48;5;%sm%s\x1b[0m\r\n", bg, line)
	}
}

type ProjectInfo struct {
	Name          string    `json:"name"`
	TaskCount     int       `json:"taskCount"`
	ResolvedCount int       `json:"resolvedCount"`
	Active        bool      `json:"active"`
	Created       time.Time `json:"created"`
	Resolved      time.Time `json:"resolved"`
	Priority      string    `json:"priority"`
}

func RenderProjects(projects []ProjectInfo) {
	if !IsTTY() {
		if projects == nil {
			projects = []ProjectInfo{}
		}
		data, _ := json.MarshalIndent(projects, "", "  ")
		fmt.Print(string(data))
		if len(projects) > 0 {
			fmt.Println()
		}
		return
	}

	if len(projects) == 0 {
		fmt.Println("0 projects.")
		return
	}

	cols, _ := GetTerminalSize()
	hdr := fmt.Sprintf("%-7s%-10s%-15s", "Name", "Progress", "Created")
	if len(hdr) < cols {
		hdr = hdr + strings.Repeat(" ", cols-len(hdr))
	}
	fmt.Printf("\x1b[4;38;5;250;48;5;232m%s\x1b[0m\r\n", hdr)

	for i, p := range projects {
		bg := "233"
		if i%2 == 1 {
			bg = "232"
		}
		progStr := fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount)
		createdStr := p.Created.Format("Mon 2 Jan 2006")
		line := fmt.Sprintf("%-7s%-10s%-15s", p.Name, progStr, createdStr)
		if len(line) < cols {
			line = line + strings.Repeat(" ", cols-len(line))
		}
		fmt.Printf("\x1b[0;38;5;250;48;5;%sm%s\x1b[0m\r\n", bg, line)
	}
}
EOF"}

